// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const texto = $json.output[0].content[0].text;

let datos;

try {
  datos = JSON.parse(texto);
} catch (e) {
  throw new Error("La IA no devolvió un JSON válido:\n\n" + texto);
}

return [
  {
    json: datos
  }
];
